mapper.update:
UPDATE vector_sync_jobs SET version=version+1, state='processing',
  attempts=attempts+1, lease_until=#{leaseUntil}, updated_at=#{now}
WHERE memory_id=#{memoryId} AND user_id=#{userId} AND version=#{version}
  AND ((state='pending' AND next_attempt_at <= #{now})
    OR (state='processing' AND lease_until <= #{now}))

UPDATE vector_sync_jobs SET state='pending', next_attempt_at=#{nextAttemptAt},
  lease_until=NULL, last_error_code=#{errorCode}, updated_at=#{nextAttemptAt}
WHERE memory_id=#{memoryId} AND user_id=#{userId}
  AND version=#{version} AND state='processing'
